import {EVIDENCE,relayObjective,terminalCommand} from './relay-house.js';
import {ITEMS,FIELD_RECIPES} from './survival.js';
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function evidencePanel(r){return `<section class="evidenceCase"><div class="eyebrow">CASE 07 / THE OCCUPIED SILENCE</div><h3>Relay House</h3><p>${relayObjective(r)}</p><div class="evidenceFlags">${[['power','Power'],['loggedIn','Account'],['filterInstalled','Filter'],['dishAligned','Dish'],['radioTuned','Carrier']].map(([k,v])=>`<span class="${r[k]?'complete':''}">${r[k]?'●':'○'} ${v}</span>`).join('')}</div><div class="evidenceGrid">${r.evidence.map(id=>`<article><span>EVIDENCE / ${esc(id.toUpperCase())}</span><h3>${EVIDENCE[id].title}</h3><p>${EVIDENCE[id].text}</p></article>`).join('')||'<p>Follow the service track west of the road, near the starting region. Look for the raised cabin and rooftop dish.</p>'}</div></section>`;}
export function equipmentSelection(s){return `<section class="itemSelection"><div class="eyebrow">EQUIP FOR USE</div><p>Choose a tool or part, then use a machine in the world. ${s.relayHouse.selected?'Selected: '+esc(ITEMS[s.relayHouse.selected].name):'E also uses the relevant part when nothing is selected.'}</p><div class="selectionGrid">${Object.entries(s.inv).filter(([id,q])=>q&&['tool','component','equipment'].includes(ITEMS[id].category)).map(([id,q])=>`<button data-use-item="${id}" aria-pressed="${s.relayHouse.selected===id}"><span class="partIcon">${ITEMS[id].category==='tool'?'⚒':ITEMS[id].category==='component'?'◈':'▣'}</span><b>${ITEMS[id].name}</b><small>× ${q} · ${ITEMS[id].mass} kg</small></button>`).join('')}<button data-use-item="">EMPTY HANDS</button></div></section>`;}
export function craftingLabel(recipe,r){return recipe.knowledge&&!r.evidence.includes(recipe.knowledge)?'LOCKED / '+recipe.knowledge+' notes':'CRAFT';}
export class RelayTerminal{
 constructor(api){this.api=api;this.lines=[];}
 open(){this.lines=['RELAY OS 07 / LOCAL TERMINAL','The world continues while you work.',this.api.state().relayHouse.loggedIn?'SESSION RESTORED / list · read · ping · dump · tune · exit':'LOCKED / login <prefix><whole-number carrier>'];this.api.enter();this.render();}
 run(command){const r=this.api.state().relayHouse;const out=terminalCommand(r,command);if(out==='EXIT'){this.api.play();return;}this.lines.push('> '+String(command).slice(0,120),out);this.lines=this.lines.slice(-22);this.api.sound.event('terminal');this.render();}
 render(){const r=this.api.state().relayHouse,panel=document.querySelector('#panel');panel.innerHTML=`<div class="terminalTop"><span>RELAY OS 07 <b class="liveDot">● LIVE</b></span><button data-terminal-exit>EXIT / B</button></div><h2>Carrier console</h2><pre class="terminalLog" aria-live="polite">${this.lines.map(esc).join('\n')}</pre><form id="relayCommandForm"><label for="relayCommand">COMMAND</label><div class="terminalInput"><input id="relayCommand" maxlength="120" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="${r.loggedIn?'ping':'login …'}"><button type="submit">SEND</button></div></form><div class="terminalShortcuts">${(r.loggedIn?['list','read operator.log','read filter.sch','ping','dump',...(r.frequencyRead?['tune 147.20']:[])]:r.noteRead&&r.frequencyRead?['login GHOST-147']:[]).map(cmd=>`<button data-terminal-command="${esc(cmd)}">${esc(cmd)}</button>`).join('')}</div><p class="hint">${r.loggedIn?'Read the operator log. Inspect the radio rack in the cellar to receive.':'Recover both paper clues to enable the account shortcut for touch and controller.'}</p>`;
  panel.querySelector('#relayCommandForm').addEventListener('submit',e=>{e.preventDefault();this.run(panel.querySelector('#relayCommand').value);});
  panel.querySelectorAll('[data-terminal-command]').forEach(b=>b.onclick=()=>this.run(b.dataset.terminalCommand));panel.querySelector('[data-terminal-exit]').onclick=()=>this.api.play();
  if(this.api.input()==='gamepad')panel.querySelector('[data-terminal-command]')?.focus();else panel.querySelector('#relayCommand').focus();
 }
}
